head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > separator]<br/>컴포넌트에서 두 개 이상의 아이템을 선택했을때 Value 값을 구분하는 구분자를 설정합니다.",
    "validation" : [            
        "validateObject() 메소드 실행 시 두 개 이상의 아이템이 선택되어 있으면 separator 속성값도 유효성 체크에 포함됩니다.",        
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof scwin.target1 !== 'undefined') {
        scwin.target1.remove();
    }    

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    let properties = {
        mandatory : true,     
        separator : "/",   
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createLabel('label="value 가 모두 빈값이고 separator 가 / 설정된 상태임"', '', 'label1');

    strTarget += '<xf:checkcombobox ' + strNameSpace + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_Item">';
    strTarget += '<xf:label ref="label"></xf:label>';
    strTarget += '<xf:value ref="value"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:checkcombobox>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "checkcombobox",
        strTarget,
        grp_comp
    );
}



scwin.btn_validateObject_onclick = function (e) {
    let rtnObj  = target1.validateObject();
    wf_body_bottom.getObj("scwin").setReturnValue("validateObject : "+ rtnObj);

    if (rtnObj) {
        let callerId = rtnObj.callerId
        let type = rtnObj.type
        let value = rtnObj.value

        wf_body_bottom.getObj("scwin").setReturnValue("callerId : "+ callerId);
        wf_body_bottom.getObj("scwin").setReturnValue("type : "+ type);
        wf_body_bottom.getObj("scwin").setReturnValue("value : "+ value);
    }
}
